class Pchip:
"""Monotone piecewise cubic Hermite interpolant (Fritsch-Carlson 1980,
slopes by Fritsch-Butland 1984). A knot value chosen at one station does
not overshoot between stations. Clamped outside the knots."""

def __init__(self, xs, ys):
self.xs, self.ys = [float(v) for v in xs], [float(v) for v in ys]
n = len(self.xs)
h = [self.xs[k + 1] - self.xs[k] for k in range(n - 1)]
d = [(self.ys[k + 1] - self.ys[k]) / h[k] for k in range(n - 1)]
m = [0.0] * n
if n == 2:
m[0] = m[1] = d[0]
else:
m[0], m[-1] = d[0], d[-1]
for k in range(1, n - 1):
if d[k - 1] * d[k] <= 0.0:
m[k] = 0.0
else:
w1, w2 = 2 * h[k] + h[k - 1], h[k] + 2 * h[k - 1]
m[k] = (w1 + w2) / (w1 / d[k - 1] + w2 / d[k])
self.m = m

def __call__(self, x):
xs, ys, m = self.xs, self.ys, self.m
if x <= xs[0]:
return ys[0]




