def loft_faces(n_stations, sides, i0, i1):
"""poly_factory topology: quads between consecutive rings, triangle fans
to the two cap centres i0 (first ring) and i1 (last ring)."""
faces = []
for si in range(n_stations - 1):
for i in range(sides):
a = si * sides + i
b = si * sides + (i + 1) % sides
c = (si + 1) * sides + (i + 1) % sides
d = (si + 1) * sides + i
faces.append((a, b, c, d))
last = (n_stations - 1) * sides
for i in range(sides):
faces.append((i0, (i + 1) % sides, i))
faces.append((i1, last + i, last + (i + 1) % sides))
return faces




